import * as React from "react"
import { TrendingDown, TrendingUp } from "lucide-react"

import { cn } from "@/lib/utils"
import { type NumberFormat } from "@/registry/dashboardcn/lib/format"
import { CornerFrame } from "@/registry/dashboardcn/ui/corner-frame"
import { MetricValue } from "@/registry/dashboardcn/ui/metric-value"
import { Sparkline } from "@/registry/dashboardcn/ui/sparkline"

export interface CommerceKpiMetric {
  label: string
  value: number
  format?: NumberFormat
  currency?: string
  delta?: number
  deltaLabel?: string
  invertDelta?: boolean
  trend?: number[]
  icon?: React.ReactNode
}

export interface CommerceKpiRowProps extends React.ComponentProps<"div"> {
  metrics: CommerceKpiMetric[]
  cornerColor?: string
}

/** A responsive row of compact commerce metrics with sparklines and registration-mark corners. */
function CommerceKpiRow({ metrics, cornerColor, className, ...props }: CommerceKpiRowProps) {
  return (
    <div
      data-slot="commerce-kpi-row"
      className={cn("grid gap-3 sm:grid-cols-2", className)}
      {...props}
    >
      {metrics.map((metric) => {
        const positive = metric.delta === undefined
          ? null
          : (metric.delta >= 0) !== Boolean(metric.invertDelta)
        const DeltaIcon = metric.delta !== undefined && metric.delta < 0 ? TrendingDown : TrendingUp
        const accent = positive === false ? "var(--color-rose-500)" : "var(--color-emerald-500)"

        return (
          <CornerFrame
            key={metric.label}
            cornerColor={cornerColor ?? "var(--muted-foreground)"}
            className="bg-card min-w-0 p-5"
          >
            <div className="flex min-w-0 items-center gap-2">
              <span className="text-muted-foreground flex min-w-0 items-center gap-1.5 truncate text-sm [&>svg]:size-3.5">
                {metric.icon}
                {metric.label}
              </span>
            </div>
            <div className="mt-2 flex items-end justify-between gap-4">
              <div className="min-w-0">
                <MetricValue
                  value={metric.value}
                  format={metric.format}
                  currency={metric.currency}
                  className="block truncate text-3xl font-semibold tracking-tight"
                />
                {metric.delta !== undefined ? (
                  <div className="text-muted-foreground mt-2 text-xs">
                    <span className="flex items-center gap-1">
                      <DeltaIcon className="size-3.5" style={{ color: accent }} />
                      <span className="font-medium tabular-nums" style={{ color: accent }}>
                        {Math.abs(metric.delta * 100).toFixed(1)}%
                      </span>
                    </span>
                    {metric.deltaLabel ? (
                      <span className="mt-0.5 block truncate">{metric.deltaLabel}</span>
                    ) : null}
                  </div>
                ) : null}
              </div>
              {metric.trend && metric.trend.length > 1 ? (
                <Sparkline
                  data={metric.trend}
                  variant="area"
                  fill="dots"
                  color="var(--muted-foreground)"
                  className="h-12 w-20 shrink-0 opacity-60"
                />
              ) : null}
            </div>
          </CornerFrame>
        )
      })}
    </div>
  )
}

export { CommerceKpiRow }

import * as React from "react"

import { cn } from "@/lib/utils"

export interface CornerFrameProps extends React.ComponentProps<"div"> {
  /** Length of each registration mark, in pixels. */
  cornerSize?: number
  /** Any CSS color used for the corner marks. */
  cornerColor?: string
  /** Show a quiet hairline around the framed content. */
  bordered?: boolean
}

/** A content frame with small registration marks at every corner. */
function CornerFrame({
  cornerSize = 10,
  cornerColor = "var(--muted-foreground)",
  bordered = true,
  className,
  children,
  style,
  ...props
}: CornerFrameProps) {
  const cornerStyle = {
    "--corner-size": `${cornerSize}px`,
    "--corner-color": cornerColor,
    ...style,
  } as React.CSSProperties

  return (
    <div
      data-slot="corner-frame"
      className={cn("relative", bordered && "border", className)}
      style={cornerStyle}
      {...props}
    >
      {children}
      {(["top-left", "top-right", "bottom-right", "bottom-left"] as const).map(
        (corner) => (
          <span
            key={corner}
            data-corner={corner}
            aria-hidden="true"
            className={cn(
              "pointer-events-none absolute z-10 size-(--corner-size)",
              "before:absolute before:bg-(--corner-color) after:absolute after:bg-(--corner-color)",
              "before:top-1/2 before:h-px before:w-full before:-translate-y-1/2 after:left-1/2 after:h-full after:w-px after:-translate-x-1/2",
              corner === "top-left" &&
                "top-0 left-0 -translate-x-1/2 -translate-y-1/2",
              corner === "top-right" &&
                "top-0 right-0 translate-x-1/2 -translate-y-1/2",
              corner === "bottom-right" &&
                "right-0 bottom-0 translate-x-1/2 translate-y-1/2",
              corner === "bottom-left" &&
                "bottom-0 left-0 -translate-x-1/2 translate-y-1/2"
            )}
          />
        )
      )}
    </div>
  )
}

export { CornerFrame }

"use client"

import * as React from "react"
import {
  Area,
  AreaChart,
  AreaRevealShape,
  Line,
  LineChart,
  ResponsiveContainer,
  type AreaRevealShapeProps,
} from "recharts"

import { cn } from "@/lib/utils"

export interface SparklineProps extends React.ComponentProps<"div"> {
  /** Series to plot, oldest first. */
  data: number[]
  variant?: "area" | "line"
  /** Area fill: a plain gradient, or a dot grid that fades out toward the line. */
  fill?: "gradient" | "dots"
  /** Any CSS color. Defaults to the theme primary. */
  color?: string
  curve?: "monotone" | "linear" | "step"
  strokeWidth?: number
  /** Animate after hydration and when data changes. Respects reduced motion. */
  animate?: boolean
  animationDuration?: number
}

const reducedMotionQuery = "(prefers-reduced-motion: reduce)"

function subscribeToReducedMotion(onChange: () => void) {
  const query = window.matchMedia(reducedMotionQuery)
  query.addEventListener("change", onChange)
  return () => query.removeEventListener("change", onChange)
}

function getReducedMotionSnapshot() {
  return window.matchMedia(reducedMotionQuery).matches
}

function getReducedMotionServerSnapshot() {
  return true
}

/** Area shape that masks the fill to a dot grid while keeping the stroke solid. */
function DotGridAreaShape({
  maskId,
  ...props
}: AreaRevealShapeProps & { maskId: string }) {
  return (
    <>
      <g mask={`url(#${maskId})`}>
        <AreaRevealShape {...props} stroke="none" />
      </g>
      <AreaRevealShape {...props} id={undefined} fill="none" />
    </>
  )
}

function Sparkline({
  data,
  variant = "area",
  fill = "gradient",
  color = "var(--primary)",
  curve = "monotone",
  strokeWidth = 1.5,
  animate = true,
  animationDuration = 500,
  className,
  ...props
}: SparklineProps) {
  const id = React.useId()
  const reducedMotion = React.useSyncExternalStore(
    subscribeToReducedMotion,
    getReducedMotionSnapshot,
    getReducedMotionServerSnapshot
  )
  const animationActive = animate && !reducedMotion
  const dots = variant === "area" && fill === "dots"
  const points = React.useMemo(() => data.map((y, i) => ({ i, y })), [data])
  const margin = { top: 2, right: 0, bottom: 0, left: 0 }

  return (
    <div
      data-slot="sparkline"
      aria-hidden="true"
      className={cn("h-10 w-full", className)}
      {...props}
    >
      <ResponsiveContainer width="100%" height="100%">
        {variant === "line" ? (
          <LineChart data={points} margin={margin}>
            <Line
              type={curve}
              dataKey="y"
              stroke={color}
              strokeWidth={strokeWidth}
              dot={false}
              isAnimationActive={animationActive}
              animationDuration={animationDuration}
              animationEasing="ease-out"
            />
          </LineChart>
        ) : (
          <AreaChart data={points} margin={margin}>
            <defs>
              <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={color} stopOpacity={dots ? 0.08 : 0.3} />
                <stop offset="100%" stopColor={color} stopOpacity={dots ? 0.9 : 0} />
              </linearGradient>
              {dots ? (
                <>
                  <pattern
                    id={`${id}-dots`}
                    patternUnits="userSpaceOnUse"
                    width={4}
                    height={4}
                  >
                    <circle cx={2} cy={2} r={0.9} fill="#fff" />
                  </pattern>
                  <mask
                    id={`${id}-mask`}
                    maskUnits="userSpaceOnUse"
                    x={0}
                    y={0}
                    width="100%"
                    height="100%"
                  >
                    <rect width="100%" height="100%" fill={`url(#${id}-dots)`} />
                  </mask>
                </>
              ) : null}
            </defs>
            <Area
              type={curve}
              dataKey="y"
              stroke={color}
              strokeWidth={strokeWidth}
              fill={`url(#${id})`}
              fillOpacity={dots ? 1 : undefined}
              dot={false}
              isAnimationActive={animationActive}
              animationDuration={animationDuration}
              animationEasing="ease-out"
              shape={
                dots
                  ? (shapeProps: AreaRevealShapeProps) => (
                      <DotGridAreaShape {...shapeProps} maskId={`${id}-mask`} />
                    )
                  : undefined
              }
            />
          </AreaChart>
        )}
      </ResponsiveContainer>
    </div>
  )
}

export { Sparkline }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

/** Values at or above this are abbreviated by default. */
export const DEFAULT_COMPACT_FROM = 100_000

export interface MetricValueProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** Strings render as-is. */
  value: number | string
  format?: NumberFormat
  currency?: string
  maximumFractionDigits?: number
  /** Values at or above this are abbreviated (e.g. $158K) with the full value in a tooltip. Set to Infinity to always show the full value. */
  compactFrom?: number
  /** Text after the number, e.g. a unit. */
  suffix?: React.ReactNode
}

/** A formatted number. Large values are abbreviated and reveal the full value on hover. */
function MetricValue({
  value,
  format,
  currency,
  maximumFractionDigits,
  compactFrom = DEFAULT_COMPACT_FROM,
  suffix,
  className,
  ...props
}: MetricValueProps) {
  const classes = cn("tabular-nums", className)

  if (typeof value !== "number") {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {value}
        {suffix}
      </span>
    )
  }

  const full = formatNumber(value, { format, currency, maximumFractionDigits })
  const abbreviate = format !== "percent" && Math.abs(value) >= compactFrom
  if (!abbreviate) {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {full}
        {suffix}
      </span>
    )
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            data-slot="metric-value"
            data-compact=""
            className={cn(classes, "cursor-default")}
            {...props}
          >
            {formatNumber(value, { format, currency, compact: true })}
            {suffix}
          </span>
        </TooltipTrigger>
        <TooltipContent className="tabular-nums">
          {full}
          {suffix}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

export { MetricValue }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
